import{_ as i,o as l,c as e,ai as r}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"监控排查实战与面试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devops/monitoring-interview.md","filePath":"guide/devops/monitoring-interview.md"}'),o={name:"guide/devops/monitoring-interview.md"};function t(n,a,s,h,d,c){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="监控排查实战与面试" tabindex="-1">监控排查实战与面试 <a class="header-anchor" href="#监控排查实战与面试" aria-label="Permalink to “监控排查实战与面试”">​</a></h1><p>目标：线上出问题知道先看哪，能把「指标 / 日志 / 链路」讲成人话，不背名词表。</p><hr><h2 id="面试高频问法" tabindex="-1">面试高频问法 <a class="header-anchor" href="#面试高频问法" aria-label="Permalink to “面试高频问法”">​</a></h2><ol><li>线上接口变慢，你怎么排查？</li><li>服务 CPU/内存打满怎么查？</li><li>你们监控看哪些核心指标？告警怎么做？</li><li>日志一般看什么字段？会不会把敏感信息打进日志？</li><li>有没有做过一次真实故障复盘？</li></ol><hr><h2 id="口述参考-短版" tabindex="-1">口述参考（短版） <a class="header-anchor" href="#口述参考-短版" aria-label="Permalink to “口述参考（短版）”">​</a></h2><p><strong>排查顺序（实用版）：</strong></p><ol><li><strong>先确认范围</strong>：单个用户 / 单个接口 / 全站？从什么时间开始？</li><li><strong>看可用性</strong>：服务是否存活、实例是否重启、部署是否刚好发生</li><li><strong>看黄金信号</strong>：延迟、流量（QPS）、错误率、饱和度（CPU/内存/连接数）</li><li><strong>看日志</strong>：错误堆栈、慢 SQL、超时、依赖调用失败</li><li><strong>再下钻</strong>：线程、GC、DB、Redis、下游超时</li></ol><p><strong>可观测三件套（人话）：</strong></p><ul><li><strong>指标</strong>：现在快不快、错不多、资源紧不紧</li><li><strong>日志</strong>：具体报了什么错</li><li><strong>链路追踪</strong>（有的话）：慢在哪一跳</li></ul><p>面试有 Prometheus/Grafana/ELK 经验就点名；没有就强调排查思路，比堆产品名重要。</p><hr><h2 id="实战-一套最小可用监控心智" tabindex="-1">实战：一套最小可用监控心智 <a class="header-anchor" href="#实战-一套最小可用监控心智" aria-label="Permalink to “实战：一套最小可用监控心智”">​</a></h2><h3 id="应用最少要暴露的感觉" tabindex="-1">应用最少要暴露的感觉 <a class="header-anchor" href="#应用最少要暴露的感觉" aria-label="Permalink to “应用最少要暴露的感觉”">​</a></h3><ul><li>接口 QPS、P95/P99 耗时、5xx 比例</li><li>JVM：堆内存、GC 次数/耗时（Java 岗很常见）</li><li>依赖：DB/Redis 连接、超时次数</li></ul><h3 id="日志最少规范" tabindex="-1">日志最少规范 <a class="header-anchor" href="#日志最少规范" aria-label="Permalink to “日志最少规范”">​</a></h3><ul><li>带 <code>traceId</code>/<code>requestId</code>（没有也要说「应该有」）</li><li>错误打堆栈，但密码、token、身份证不要明文</li><li>关键路径单独关键字，方便 grep</li></ul><h3 id="告警最少原则" tabindex="-1">告警最少原则 <a class="header-anchor" href="#告警最少原则" aria-label="Permalink to “告警最少原则”">​</a></h3><ul><li>告警要能行动：不是「CPU 高了」就完，要知道找谁、先看哪</li><li>先保命：服务挂、错误率飙升、磁盘满</li><li>避免告警风暴：合并、降噪、分级</li></ul><hr><h2 id="一道题练口述-接口突然变慢" tabindex="-1">一道题练口述：接口突然变慢 <a class="header-anchor" href="#一道题练口述-接口突然变慢" aria-label="Permalink to “一道题练口述：接口突然变慢”">​</a></h2><p>可以这样答：</p><blockquote><p>先确认是否刚发版、是否个别接口。然后看该接口耗时和错误率，再看 DB/Redis 耗时。若是慢 SQL 就 explain 和索引；若是下游超时就看依赖和线程是否打满；同时用日志定位具体异常。处理完会补监控项和告警，避免同样问题第二次才发现。</p></blockquote><hr><h2 id="结合你简历怎么讲" tabindex="-1">结合你简历怎么讲 <a class="header-anchor" href="#结合你简历怎么讲" aria-label="Permalink to “结合你简历怎么讲”">​</a></h2><p>业务系统 / MES 现场交付可以说：</p><blockquote><p>联调和上线后更关注服务是否稳定、接口是否超时、采集链路是否中断。问题一般从日志和资源占用入手，先恢复再复盘。</p></blockquote><p>有大盘/告警经验再补工具名；没有就别硬编完整 ELK 体系。</p><hr><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to “常见坑”">​</a></h2><ul><li>只看 CPU，不看错误率和依赖耗时</li><li>日志巨多但没有 requestId，无法串一次请求</li><li>告警太多没人理 = 等于没告警</li></ul><hr><h2 id="自测清单" tabindex="-1">自测清单 <a class="header-anchor" href="#自测清单" aria-label="Permalink to “自测清单”">​</a></h2><ul><li>[ ] 能按顺序说：范围 → 存活 → 黄金信号 → 日志 → 下钻</li><li>[ ] 能举一个自己排查过的慢接口/发版问题</li><li>[ ] 知道日志里不该打什么</li><li>[ ] 能说出 3～5 个你认为必须盯的指标</li></ul>',35)])])}const u=i(o,[["render",t]]);export{g as __pageData,u as default};
